CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, name text NOT NULL, password_hash text NOT NULL, role text NOT NULL CHECK(role IN ('STUDENT','MESS_ADMIN','ADMIN')), status text NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','INACTIVE')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE students(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL UNIQUE REFERENCES users(id),student_id text NOT NULL UNIQUE,registration_number text NOT NULL,hostel text NOT NULL,room_number text NOT NULL,phone text,status text NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','INACTIVE')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),token_hash text NOT NULL UNIQUE,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE meal_windows(meal text PRIMARY KEY CHECK(meal IN ('BREAKFAST','LUNCH','DINNER')),start_time text NOT NULL,end_time text NOT NULL,cutoff_time text NOT NULL,CHECK(start_time < end_time),CHECK(cutoff_time <= start_time));
INSERT INTO meal_windows VALUES ('BREAKFAST','07:30','09:30','07:00'),('LUNCH','12:00','14:30','11:00'),('DINNER','19:00','21:30','18:00');
CREATE TABLE meal_preferences(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),student_id uuid NOT NULL REFERENCES students(id),date date NOT NULL,meal text NOT NULL REFERENCES meal_windows(meal),response text NOT NULL CHECK(response IN ('COMING','NOT_COMING')),updated_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT preference_student_meal_date UNIQUE(student_id,date,meal));
CREATE INDEX preferences_date_meal ON meal_preferences(date,meal);
CREATE TABLE fingerprint_mappings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),student_id uuid NOT NULL UNIQUE REFERENCES students(id),fingerprint_id integer NOT NULL UNIQUE CHECK(fingerprint_id BETWEEN 1 AND 1000),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE devices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),device_id text NOT NULL UNIQUE,name text NOT NULL,type text NOT NULL CHECK(type IN ('FINGERPRINT_SCANNER','WASTE_MONITOR')),status text NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','DISABLED')),token_hash text NOT NULL UNIQUE,last_seen timestamptz,last_result text,firmware_version text,capacity_kg double precision NOT NULL DEFAULT 20 CHECK(capacity_kg>0),high_water_kg double precision NOT NULL DEFAULT 0 CHECK(high_water_kg>=0),tare_session integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE attendance(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),student_id uuid NOT NULL REFERENCES students(id),date date NOT NULL,meal text NOT NULL REFERENCES meal_windows(meal),check_in_time timestamptz NOT NULL DEFAULT now(),fingerprint_id integer,source text NOT NULL CHECK(source IN ('FINGERPRINT','MANUAL','IMPORT')),device_id uuid REFERENCES devices(id),reason text,created_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT attendance_student_meal_date UNIQUE(student_id,date,meal));
CREATE INDEX attendance_date_meal ON attendance(date,meal);
CREATE TABLE waste_measurements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),device_id uuid NOT NULL REFERENCES devices(id),measurement_id uuid NOT NULL,weight_kg double precision NOT NULL CHECK(weight_kg>=0),delta_kg double precision NOT NULL CHECK(delta_kg>=0),tare boolean NOT NULL DEFAULT false,tare_session integer NOT NULL,date date NOT NULL,meal text REFERENCES meal_windows(meal),measured_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT measurement_device_event UNIQUE(device_id,measurement_id));
CREATE INDEX waste_date_meal ON waste_measurements(date,meal);
CREATE TABLE food_preparations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),date date NOT NULL,meal text NOT NULL REFERENCES meal_windows(meal),weight_kg double precision NOT NULL CHECK(weight_kg>0),estimated_cost double precision NOT NULL CHECK(estimated_cost>=0),CONSTRAINT preparation_date_meal UNIQUE(date,meal));
CREATE TABLE system_settings(key text PRIMARY KEY,value jsonb NOT NULL);
INSERT INTO system_settings VALUES ('assumptions','{"costPerKg":null,"baselineWastePerStudent":null,"co2PerKg":null,"waterLitresPerKg":null,"portionKg":null,"onlineThresholdMinutes":5}');
CREATE TABLE predictions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),date date NOT NULL,meal text NOT NULL REFERENCES meal_windows(meal),attendance integer NOT NULL CHECK(attendance>=0),waste_kg double precision,food_kg double precision,source text NOT NULL,sample_count integer NOT NULL,inputs jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT prediction_date_meal UNIQUE(date,meal));
CREATE TABLE prediction_results(prediction_id uuid PRIMARY KEY REFERENCES predictions(id),actual_attendance integer NOT NULL,actual_waste double precision NOT NULL,evaluated_at timestamptz NOT NULL);
CREATE TABLE audit_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_id uuid REFERENCES users(id),actor_role text,action text NOT NULL,entity text NOT NULL,entity_id text,metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_created ON audit_logs(created_at DESC);
CREATE TABLE rate_limits(key text PRIMARY KEY,count integer NOT NULL,expires_at timestamptz NOT NULL);
CREATE INDEX rate_limits_expiry ON rate_limits(expires_at);
